let links=document.querySelectorAll('nav a[href^="#"]'),secoes=document.querySelectorAll("main section[id]");function marcarAtivo(o){links.forEach(function(e){var t=e.getAttribute("href")==="#"+o;e.classList.toggle("ativo",t),t?(e.setAttribute("aria-current","true"),e.scrollIntoView({block:"nearest",inline:"center"})):e.removeAttribute("aria-current")})}let observador=new IntersectionObserver(function(e){e.forEach(function(e){e.isIntersecting&&marcarAtivo(e.target.id)})},{rootMargin:"-45% 0px -50% 0px"}),voltarTopo=(secoes.forEach(function(e){observador.observe(e)}),document.getElementById("voltar-topo"));window.addEventListener("scroll",function(){voltarTopo.classList.toggle("visivel",600<window.scrollY)},{passive:!0}),voltarTopo.addEventListener("click",function(e){e.preventDefault(),window.scrollTo({top:0}),document.getElementById("conteudo").focus({preventScroll:!0})});